css:
.demo-plugin-root {
  font-family: ui-sans-serif, system-ui, sans-serif;
  padding: 16px;
  background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
  border-radius: 8px;
  color: #1f2937;
}
.demo-plugin-root h3 { margin: 0 0 8px; font-size: 16px; }
.demo-plugin-root p { margin: 0 0 12px; font-size: 13px; color: #4b5563; }
.demo-plugin-root button {
  padding: 4px 12px;
  border: 1px solid #1f2937;
  background: white;
  border-radius: 4px;
  cursor: pointer;
  font-size: 13px;
}
